import { FocusOrigin } from '@angular/cdk/a11y';

import { Directive, ElementRef, inject, input, OnDestroy, output, DOCUMENT } from '@angular/core';
import { QMenuComponent } from './menu.component';

interface HTMLElementWithPopover extends HTMLElement {
  showPopover: (options?: { source?: HTMLElement }) => void;
  hidePopover: () => void;
}

@Directive({
  selector: '[qContextMenuTriggerFor]',
  exportAs: 'qContextMenuTrigger',
  host: {
    'class': 'q-context-menu-trigger',
    '[attr.data-qt]': 'dataQt()',
    '[attr.aria-controls]': '_ariaControls()',
    '(contextmenu)': '_handleContextMenuEvent($event)',
  },
})
export class QContextMenuTriggerDirective implements OnDestroy {
  readonly menuOpened = output();
  readonly menuClosed = output();

  menu = input<QMenuComponent | null>(null, { alias: 'qContextMenuTriggerFor' });
  disabled = input(false, { alias: 'qContextMenuTriggerDisabled' });
  dataQt = input('q-context-menu-trigger', { alias: 'qContextMenuTriggerDataQt' });

  private _document = inject(DOCUMENT);
  private _element = inject<ElementRef<HTMLElement>>(ElementRef);
  private _anchorEl: HTMLElement | null = null;
  private _menuOpen = false;
  private _openedBy: FocusOrigin | null = null;
  private _triggerPressedControl = false;
  private _cleanupManualDismiss: (() => void) | null = null;

  ngOnDestroy(): void {
    this._cleanupAnchor();
  }

  _handleContextMenuEvent(event: MouseEvent): void {
    if (this.disabled()) return;
    event.preventDefault();
    event.stopPropagation();

    const x = event.clientX;
    const y = event.clientY;
    const ctrl = !!event.ctrlKey;

    if (this._menuOpen) {
      const menu = this.menu();
      if (menu) {
        const host = menu._getHostElement();
        if (host) {
          const closedSub = menu._popoverDirective.closed.subscribe(() => {
            closedSub.unsubscribe();
            this._positionAnchor(x, y);
            this._openContextMenuAt(x, y, ctrl);
          });

          host.hidePopover();
          this._menuOpen = false;
          this._cleanupManualDismiss?.();
          this._cleanupManualDismiss = null;
          this.menuClosed.emit();
        }
      }
    } else {
      this._openContextMenuAt(x, y, ctrl);
    }
  }

  _ariaControls(): string | null {
    const menu = this.menu();
    return this._menuOpen && menu ? menu._menuId : null;
  }

  private _openContextMenuAt(x: number, y: number, ctrlKey: boolean): void {
    const menu = this.menu();
    if (!menu) return;

    this._openedBy = 'mouse';
    this._triggerPressedControl = ctrlKey;

    this._ensureAnchor();
    this._positionAnchor(x, y);

    menu._popoverDirective.setPopoverTriggerElement(this._anchorEl);

    const host = menu._getHostElement();
    if (!host) return;

    host.setAttribute('popover', 'manual');

    (host as HTMLElementWithPopover).showPopover();
    this._suppressNextOutsidePointerBurst(menu);
    this._installManualDismissHandlers(menu);
    this._menuOpen = true;
    this.menuOpened.emit();
    host.focus();

    const sub = menu.closed.subscribe(() => {
      if (this._menuOpen) {
        this._menuOpen = false;
        const hostEl = menu._getHostElement();
        const handleAfterPopoverClosed = (): void => {
          hostEl?.setAttribute('popover', 'auto');
          this._cleanupManualDismiss?.();
          this._cleanupManualDismiss = null;
          this._cleanupAnchor();
          this._focus();
          this.menuClosed.emit();
        };

        if (hostEl && hostEl.matches(':popover-open')) {
          const popoverClosedSub = menu._popoverDirective.closed.subscribe(() => {
            popoverClosedSub.unsubscribe();
            handleAfterPopoverClosed();
          });
          hostEl.hidePopover();
        } else {
          handleAfterPopoverClosed();
        }
      }
      sub.unsubscribe();
    });
  }

  private _ensureAnchor(): void {
    if (!this._anchorEl) {
      const el = this._document.createElement('div');
      el.style.position = 'fixed';
      el.style.width = '0';
      el.style.height = '0';
      el.style.pointerEvents = 'none';
      el.style.zIndex = '0';
      this._document.body.appendChild(el);
      this._anchorEl = el;
    }
  }

  private _positionAnchor(x: number, y: number): void {
    if (this._anchorEl) {
      this._anchorEl.style.left = `${x}px`;
      this._anchorEl.style.top = `${y}px`;
    }
  }

  private _cleanupAnchor(): void {
    if (this._anchorEl && this._anchorEl.isConnected) {
      this._anchorEl.remove();
    }
    this._anchorEl = null;
  }

  private _focus(): void {
    this._element.nativeElement.focus({ preventScroll: true });
  }

  private _suppressNextOutsidePointerBurst(menu: QMenuComponent): void {
    const opts: AddEventListenerOptions = { capture: true, once: true, passive: false };
    let firstAux = true;

    const isWithinMenuOrTrigger = (target: Element | null): boolean => {
      if (!target) return false;
      const triggerEl = this._element.nativeElement;
      if (target === triggerEl || triggerEl.contains(target)) return true;
      const panelEl = menu._getHostElement();
      return !!panelEl && (target === panelEl || panelEl.contains(target));
    };

    const swallowIfOutside = (ev: Event): void => {
      if (!this._menuOpen) return;
      const e = ev as MouseEvent;
      let target: Element | null = ev.target as Element | null;
      if (ev.type === 'auxclick' && (!target || target === this._document.body)) {
        target = this._document.elementFromPoint(e.clientX, e.clientY);
      }
      const inside = isWithinMenuOrTrigger(target);

      if (ev.type === 'mouseup' || ev.type === 'pointerup') {
        e.stopPropagation();
        (e as unknown as { stopImmediatePropagation?: () => void }).stopImmediatePropagation?.();
        return;
      }

      if (inside) {
        return;
      }

      if (ev.type === 'auxclick') {
        if (firstAux) {
          firstAux = false;
        } else {
          return;
        }
      }
      e.stopPropagation();
      (e as unknown as { stopImmediatePropagation?: () => void }).stopImmediatePropagation?.();
    };

    this._document.addEventListener('mouseup', swallowIfOutside, opts);
    this._document.addEventListener('pointerup', swallowIfOutside as EventListener, opts);
  }

  private _installManualDismissHandlers(menu: QMenuComponent): void {
    this._cleanupManualDismiss?.();

    const doc = this._document;
    const panelEl = menu._getHostElement();

    if (!panelEl) {
      this._cleanupManualDismiss = null;
      return;
    }

    const onPointerDown = (ev: PointerEvent): void => {
      if (!this._menuOpen) return;
      const target = ev.target as Element | null;

      if (target && (target.closest('.q-menu') || panelEl.contains(target))) {
        return;
      }

      panelEl.hidePopover();
    };

    doc.addEventListener('pointerdown', onPointerDown, false);

    this._cleanupManualDismiss = (): void => {
      doc.removeEventListener('pointerdown', onPointerDown, false);
    };
  }
}
