import { FocusableOption, FocusMonitor, FocusOrigin } from '@angular/cdk/a11y';

import {
  AfterViewInit,
  booleanAttribute,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  ElementRef,
  inject,
  input,
  Input,
  OnDestroy,
  OnInit,
  ViewEncapsulation,
  DOCUMENT,
} from '@angular/core';
import { QIconComponent, QIconRegistryService } from '@questrade/allspark-angular-components/icon';
import { chevronRight } from '@questrade/allspark-icons/icons';
import { Subject } from 'rxjs';
import { QMenuComponent } from './menu.component';

@Component({
  selector: '[q-menu-item]',
  templateUrl: './menu-item.component.html',
  styleUrl: './menu-item.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  imports: [QIconComponent],
  host: {
    'class': 'q-menu-item q-focus-indicator-inset',
    '[class.q-menu-item-highlighted]': '_highlighted',
    '[attr.role]': "'menuitem'",
    '[attr.tabindex]': '_getTabIndex()',
    '[attr.data-qt]': 'dataQt()',
    '[attr.aria-disabled]': 'disabled',
    '[attr.disabled]': 'disabled || null',
    '(click)': '_handleClick($event)',
    '(mouseenter)': '_handleMouseEnter()',
  },
})
export class QMenuItemComponent implements FocusableOption, OnInit, AfterViewInit, OnDestroy {
  @Input({ transform: booleanAttribute, alias: 'qMenuItemDisabled' }) disabled = false;
  dataQt = input('q-menu-item', { alias: 'qMenuItemDataQt' });

  _highlighted = false;
  _triggersSubmenu = false;
  readonly _parentMenu = inject(QMenuComponent, { optional: true });
  readonly _hovered = new Subject<QMenuItemComponent>();
  readonly _focused = new Subject<QMenuItemComponent>();
  private readonly _elementRef = inject<ElementRef<HTMLElement>>(ElementRef);
  private readonly _document = inject(DOCUMENT);
  private readonly _focusMonitor = inject(FocusMonitor);
  private readonly _cdr = inject(ChangeDetectorRef);
  private readonly _iconRegistry = inject(QIconRegistryService);

  ngOnInit(): void {
    this._iconRegistry.registerIcons([chevronRight]);
  }

  ngAfterViewInit(): void {
    if (this._focusMonitor) {
      this._focusMonitor.monitor(this._elementRef, false);
    }
  }

  ngOnDestroy(): void {
    if (this._focusMonitor) {
      this._focusMonitor.stopMonitoring(this._elementRef);
    }

    this._hovered.complete();
    this._focused.complete();
  }

  focus(origin?: FocusOrigin, options?: FocusOptions): void {
    if (this._focusMonitor && origin) {
      this._focusMonitor.focusVia(this._getHostElement(), origin, options);
    } else {
      this._getHostElement().focus(options);
    }

    this._focused.next(this);
  }

  getLabel(): string {
    const clone = this._elementRef.nativeElement.cloneNode(true) as HTMLElement;
    const icons = clone.querySelectorAll('q-icon');

    for (const icon of icons) {
      icon.remove();
    }

    return clone.textContent?.trim() || '';
  }

  _getTabIndex(): string {
    return this.disabled ? '-1' : '0';
  }

  _handleClick(event: Event): void {
    if (this.disabled || this._triggersSubmenu) {
      event.preventDefault();
      event.stopPropagation();
      return;
    }
  }

  _handleMouseEnter(): void {
    this._hovered.next(this);
  }

  _setHighlighted(isHighlighted: boolean): void {
    this._highlighted = isHighlighted;
    this._cdr.markForCheck();
  }

  _setTriggersSubmenu(triggersSubmenu: boolean): void {
    this._triggersSubmenu = triggersSubmenu;
    this._cdr.markForCheck();
  }

  _hasFocus(): boolean {
    return this._document && this._document.activeElement === this._getHostElement();
  }

  private _getHostElement(): HTMLElement {
    return this._elementRef.nativeElement;
  }
}
