import { FocusKeyManager, FocusOrigin } from '@angular/cdk/a11y';
import { hasModifierKey } from '@angular/cdk/keycodes';
import {
  AfterContentInit,
  afterNextRender,
  AfterRenderRef,
  AfterViewInit,
  ChangeDetectionStrategy,
  Component,
  contentChildren,
  effect,
  ElementRef,
  forwardRef,
  inject,
  Injector,
  input,
  OnDestroy,
  output,
  QueryList,
  ViewEncapsulation,
} from '@angular/core';
import {
  DOWN_ARROW,
  ESCAPE,
  LEFT_ARROW,
  randomString,
  UP_ARROW,
} from '@questrade/allspark-angular-components/core/utils';
import { QPopoverDirective } from '@questrade/allspark-angular-components/popover';
import { merge, Observable } from 'rxjs';
import { startWith, switchMap } from 'rxjs/operators';
import { QMenuItemComponent } from './menu-item.component';
import { QMenuCloseReason } from './types/menu-close-reason.type';

@Component({
  selector: 'q-menu',
  exportAs: 'qMenu',
  template: `<ng-content />`,
  styleUrl: './menu.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  host: {
    'class': 'q-menu',
    'role': 'menu',
    'tabindex': '-1',
    'popover': 'auto',
    '[attr.id]': '_menuId',
    '[attr.data-qt]': 'dataQt()',
    '[attr.aria-label]': 'ariaLabel() || null',
    '[attr.aria-labelledby]': 'ariaLabelledby() || null',
    '[attr.aria-describedby]': 'ariaDescribedby() || null',
    '(keydown)': '_handleKeydown($event)',
    '(click)': '_handleClick($event)',
  },
  hostDirectives: [
    {
      directive: QPopoverDirective,
      inputs: ['qPopoverPlacement: placement', 'qPopoverOffset: offset'],
    },
  ],
})
export class QMenuComponent implements AfterContentInit, AfterViewInit, OnDestroy {
  readonly closed = output<QMenuCloseReason>();

  ariaLabel = input('');
  ariaLabelledby = input('');
  ariaDescribedby = input('');
  dataQt = input('q-menu');

  _allItems = contentChildren(
    forwardRef(() => QMenuItemComponent),
    { descendants: true },
  );
  _parentMenu: QMenuComponent | null = null;
  readonly _menuId = `q-menu-${randomString()}`;
  readonly _popoverDirective = inject(QPopoverDirective, { host: true });
  private _directDescendantItems = new QueryList<QMenuItemComponent>();
  private _hasDirectEmission = false;
  private _keyManager: FocusKeyManager<QMenuItemComponent> | null = null;
  private _firstItemFocusRef: AfterRenderRef | null = null;
  private readonly _elementRef = inject<ElementRef<HTMLElement>>(ElementRef);
  private readonly _injector = inject(Injector);

  constructor() {
    effect(() => {
      const items = this._allItems();
      this._directDescendantItems.reset(items.filter((item) => item._parentMenu === this));
      this._directDescendantItems.notifyOnChanges();
    });
  }

  ngAfterViewInit(): void {
    this._setupPopoverClosedSubscription();
  }

  ngAfterContentInit(): void {
    this._setupKeyManager();
    this._setupTabOutSubscription();
    this._setupFocusedItemTracking();
    this._setupItemsChangesHandling();
  }

  ngOnDestroy(): void {
    this._keyManager?.destroy();
    this._directDescendantItems.destroy();
    this._firstItemFocusRef?.destroy();
  }

  focusFirstItem(origin: FocusOrigin = 'program'): void {
    this._firstItemFocusRef?.destroy();
    this._firstItemFocusRef = afterNextRender(
      () => {
        const menuPanel = this._resolvePanel();

        if (!menuPanel || !menuPanel.contains(document.activeElement)) {
          const manager = this._keyManager;
          manager?.setFocusOrigin(origin).setFirstItemActive();

          if (!manager?.activeItem && menuPanel) {
            menuPanel.focus();
          }
        }
      },
      { injector: this._injector },
    );
  }

  resetActiveItem(): void {
    this._keyManager?.setActiveItem(-1);
  }

  _hovered(): Observable<QMenuItemComponent> {
    const itemChanges = this._directDescendantItems.changes as Observable<
      QueryList<QMenuItemComponent>
    >;
    return itemChanges.pipe(
      startWith(this._directDescendantItems),
      switchMap((items) => merge(...items.map((item: QMenuItemComponent) => item._hovered))),
    );
  }

  _handleKeydown(event: KeyboardEvent): void {
    const code = event.code;
    const manager = this._keyManager;

    switch (code) {
      case ESCAPE:
        // Prevent native popover Escape behavior even with modifiers.
        event.preventDefault();
        if (!hasModifierKey(event)) {
          this._hasDirectEmission = true;
          this.closed.emit('keydown');
        }
        break;
      case LEFT_ARROW:
        if (this._parentMenu) {
          this._hasDirectEmission = true;
          this.closed.emit('keydown');
        }
        break;
      default:
        if (code === UP_ARROW || code === DOWN_ARROW) {
          manager?.setFocusOrigin('keyboard');
        }

        manager?.onKeydown(event);
        return;
    }
  }

  _handleClick(event: Event): void {
    const target = event.target as Element;
    const menuItem = target?.closest('[q-menu-item]');

    if (menuItem && !event.defaultPrevented) {
      this._setDirectEmissionFlag();
      this.closed.emit('click');
    }
  }

  _getHostElement(): HTMLElement {
    return this._elementRef.nativeElement;
  }

  _setDirectEmissionFlag(): void {
    this._hasDirectEmission = true;
  }

  private _setupPopoverClosedSubscription(): void {
    this._popoverDirective.closed.subscribe(() => {
      if (!this._hasDirectEmission) {
        this.closed.emit('none');
      }
      this._hasDirectEmission = false;
    });
  }

  private _setupKeyManager(): void {
    this._keyManager = new FocusKeyManager(this._directDescendantItems)
      .withWrap()
      .withTypeAhead()
      .withHomeAndEnd();
  }

  private _setupTabOutSubscription(): void {
    this._keyManager?.tabOut.subscribe(() => {
      this._hasDirectEmission = true;
      this.closed.emit('tab');
    });
  }

  private _setupFocusedItemTracking(): void {
    this._directDescendantItems.changes
      .pipe(
        startWith(this._directDescendantItems),
        switchMap((items) => merge(...items.map((item: QMenuItemComponent) => item._focused))),
      )
      .subscribe((focusedItem) =>
        this._keyManager?.updateActiveItem(focusedItem as QMenuItemComponent),
      );
  }

  private _setupItemsChangesHandling(): void {
    this._directDescendantItems.changes.subscribe((itemsList: QueryList<QMenuItemComponent>) => {
      const manager = this._keyManager;

      if (manager?.activeItem?._hasFocus()) {
        const items = itemsList.toArray();
        const index = Math.max(0, Math.min(items.length - 1, manager.activeItemIndex || 0));

        if (items[index] && !items[index].disabled) {
          manager.setActiveItem(index);
        } else {
          manager.setNextItemActive();
        }
      }
    });
  }

  private _resolvePanel(): HTMLElement | null {
    let menuPanel: HTMLElement | null = null;

    if (this._directDescendantItems.length) {
      menuPanel = this._elementRef.nativeElement;
    }

    return menuPanel;
  }
}
